-- The declared name and the declared START WITH are one option list, so both survive.
-- @setup
CREATE TABLE idsns (id INT GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME idsns_custom START WITH 3));
INSERT INTO idsns (id) VALUES (DEFAULT);
SELECT setval('idsns_custom', 10, true);
INSERT INTO idsns (id) VALUES (DEFAULT);
-- @test
SELECT id FROM idsns ORDER BY id;
